void cJSON_DeleteMarkConfig(struct MarkConfig * x) {
    if (NULL != x) {
        if (NULL != x->align) {
            cJSON_free(x->align);
        }
        if (NULL != x->angle) {
            cJSON_free(x->angle);
        }
        if (NULL != x->baseline) {
            cJSON_free(x->baseline);
        }
        if (NULL != x->color) {
            cJSON_free(x->color);
        }
        if (NULL != x->cursor) {
            cJSON_free(x->cursor);
        }
        if (NULL != x->dx) {
            cJSON_free(x->dx);
        }
        if (NULL != x->dy) {
            cJSON_free(x->dy);
        }
        if (NULL != x->fill) {
            cJSON_free(x->fill);
        }
        if (NULL != x->filled) {
            cJSON_free(x->filled);
        }
        if (NULL != x->fill_opacity) {
            cJSON_free(x->fill_opacity);
        }
        if (NULL != x->font) {
            cJSON_free(x->font);
        }
        if (NULL != x->font_size) {
            cJSON_free(x->font_size);
        }
        if (NULL != x->font_style) {
            cJSON_free(x->font_style);
        }
        if (NULL != x->font_weight) {
            cJSON_DeleteFontWeightUnion(x->font_weight);
        }
        if (NULL != x->href) {
            cJSON_free(x->href);
        }
        if (NULL != x->interpolate) {
            cJSON_free(x->interpolate);
        }
        if (NULL != x->limit) {
            cJSON_free(x->limit);
        }
        if (NULL != x->opacity) {
            cJSON_free(x->opacity);
        }
        if (NULL != x->orient) {
            cJSON_free(x->orient);
        }
        if (NULL != x->radius) {
            cJSON_free(x->radius);
        }
        if (NULL != x->shape) {
            cJSON_free(x->shape);
        }
        if (NULL != x->size) {
            cJSON_free(x->size);
        }
        if (NULL != x->stroke) {
            cJSON_free(x->stroke);
        }
        if (NULL != x->stroke_dash) {
            double * x1 = list_get_head(x->stroke_dash);
            while (NULL != x1) {
                cJSON_free(x1);
                x1 = list_get_next(x->stroke_dash);
            }
            list_release(x->stroke_dash);
        }
        if (NULL != x->stroke_dash_offset) {
            cJSON_free(x->stroke_dash_offset);
        }
        if (NULL != x->stroke_opacity) {
            cJSON_free(x->stroke_opacity);
        }
        if (NULL != x->stroke_width) {
            cJSON_free(x->stroke_width);
        }
        if (NULL != x->tension) {
            cJSON_free(x->tension);
        }
        if (NULL != x->text) {
            cJSON_free(x->text);
        }
        if (NULL != x->theta) {
            cJSON_free(x->theta);
        }
        cJSON_free(x);
    }
}

