void cJSON_DeleteProjectionConfig(struct ProjectionConfig * x) {
    if (NULL != x) {
        if (NULL != x->center) {
            double * x1 = list_get_head(x->center);
            while (NULL != x1) {
                cJSON_free(x1);
                x1 = list_get_next(x->center);
            }
            list_release(x->center);
        }
        if (NULL != x->clip_angle) {
            cJSON_free(x->clip_angle);
        }
        if (NULL != x->clip_extent) {
            list_t * x1 = list_get_head(x->clip_extent);
            while (NULL != x1) {
                double * x2 = list_get_head(x1);
                while (NULL != x2) {
                    cJSON_free(x2);
                    x2 = list_get_next(x1);
                }
                list_release(x1);
                x1 = list_get_next(x->clip_extent);
            }
            list_release(x->clip_extent);
        }
        if (NULL != x->coefficient) {
            cJSON_free(x->coefficient);
        }
        if (NULL != x->distance) {
            cJSON_free(x->distance);
        }
        if (NULL != x->fraction) {
            cJSON_free(x->fraction);
        }
        if (NULL != x->lobes) {
            cJSON_free(x->lobes);
        }
        if (NULL != x->parallel) {
            cJSON_free(x->parallel);
        }
        if (NULL != x->precision) {
            char **keys1 = NULL;
            size_t count1 = hashtable_get_keys(x->precision, &keys1);
            if (NULL != keys1) {
                for (size_t index1 = 0; index1 < count1; index1++) {
                    struct TitleFontWeight *x1 = hashtable_lookup(x->precision, keys1[index1]);
                    if (NULL != x1) {
                        cJSON_DeleteTitleFontWeight(x1);
                    }
                }
                cJSON_free(keys1);
            }
            hashtable_release(x->precision);
        }
        if (NULL != x->radius) {
            cJSON_free(x->radius);
        }
        if (NULL != x->ratio) {
            cJSON_free(x->ratio);
        }
        if (NULL != x->rotate) {
            double * x1 = list_get_head(x->rotate);
            while (NULL != x1) {
                cJSON_free(x1);
                x1 = list_get_next(x->rotate);
            }
            list_release(x->rotate);
        }
        if (NULL != x->spacing) {
            cJSON_free(x->spacing);
        }
        if (NULL != x->tilt) {
            cJSON_free(x->tilt);
        }
        if (NULL != x->type) {
            cJSON_free(x->type);
        }
        cJSON_free(x);
    }
}

