cJSON * cJSON_CreateProjection(const struct Projection * x) {
    cJSON * j = NULL;
    if (NULL != x) {
        if (NULL != (j = cJSON_CreateObject())) {
            if (NULL != x->center) {
                cJSON * j1 = cJSON_AddArrayToObject(j, "center");
                if (NULL != j1) {
                    double * x1 = list_get_head(x->center);
                    while (NULL != x1) {
                        cJSON_AddItemToArray(j1, cJSON_CreateNumber(*x1));
                        x1 = list_get_next(x->center);
                    }
                }
            }
            if (NULL != x->clip_angle) {
                cJSON_AddNumberToObject(j, "clipAngle", *x->clip_angle);
            }
            if (NULL != x->clip_extent) {
                cJSON * j1 = cJSON_AddArrayToObject(j, "clipExtent");
                if (NULL != j1) {
                    list_t * x1 = list_get_head(x->clip_extent);
                    while (NULL != x1) {
                        cJSON * j2 = cJSON_CreateArray();
                        if (NULL != j2) {
                            double * x2 = list_get_head(x1);
                            while (NULL != x2) {
                                cJSON_AddItemToArray(j2, cJSON_CreateNumber(*x2));
                                x2 = list_get_next(x1);
                            }
                        }
                        cJSON_AddItemToArray(j1, j2);
                        x1 = list_get_next(x->clip_extent);
                    }
                }
            }
            if (NULL != x->coefficient) {
                cJSON_AddNumberToObject(j, "coefficient", *x->coefficient);
            }
            if (NULL != x->distance) {
                cJSON_AddNumberToObject(j, "distance", *x->distance);
            }
            if (NULL != x->fraction) {
                cJSON_AddNumberToObject(j, "fraction", *x->fraction);
            }
            if (NULL != x->lobes) {
                cJSON_AddNumberToObject(j, "lobes", *x->lobes);
            }
            if (NULL != x->parallel) {
                cJSON_AddNumberToObject(j, "parallel", *x->parallel);
            }
            if (NULL != x->precision) {
                cJSON * j1 = cJSON_CreateObject();
                if (NULL != j1) {
                    char **keys1 = NULL;
                    size_t count1 = hashtable_get_keys(x->precision, &keys1);
                    if (NULL != keys1) {
                        for (size_t index1 = 0; index1 < count1; index1++) {
                            struct TitleFontWeight *x1 = hashtable_lookup(x->precision, keys1[index1]);
                            cJSON_AddItemToObject(j1, keys1[index1], cJSON_CreateTitleFontWeight(x1));
                        }
                        cJSON_free(keys1);
                    }
                    cJSON_AddItemToObject(j, "precision", j1);
                }
            }
            if (NULL != x->radius) {
                cJSON_AddNumberToObject(j, "radius", *x->radius);
            }
            if (NULL != x->ratio) {
                cJSON_AddNumberToObject(j, "ratio", *x->ratio);
            }
            if (NULL != x->rotate) {
                cJSON * j1 = cJSON_AddArrayToObject(j, "rotate");
                if (NULL != j1) {
                    double * x1 = list_get_head(x->rotate);
                    while (NULL != x1) {
                        cJSON_AddItemToArray(j1, cJSON_CreateNumber(*x1));
                        x1 = list_get_next(x->rotate);
                    }
                }
            }
            if (NULL != x->spacing) {
                cJSON_AddNumberToObject(j, "spacing", *x->spacing);
            }
            if (NULL != x->tilt) {
                cJSON_AddNumberToObject(j, "tilt", *x->tilt);
            }
            if (NULL != x->type) {
                cJSON_AddItemToObject(j, "type", cJSON_CreateVgProjectionType(*x->type));
            }
        }
    }
    return j;
}

